-- ─────────────────────────────────────────────────────────────
-- 1. Función helper (se elimina al final)
-- ─────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION bauth._rt_ins(
  p_ten  UUID,
  p_par  TEXT,
  p_path TEXT,
  p_tipo TEXT,
  p_clav TEXT,
  p_name TEXT,
  p_val  TEXT    DEFAULT NULL,
  p_help TEXT    DEFAULT NULL,
  p_opc  TEXT[]  DEFAULT '{}',
  p_eff  BOOLEAN DEFAULT false,
  p_verb TEXT    DEFAULT NULL,
  p_dnum INTEGER DEFAULT NULL,
  p_cond JSONB   DEFAULT NULL
) RETURNS UUID LANGUAGE plpgsql AS $func$
DECLARE
  v_pid UUID;
  v_dep INTEGER := 0;
  v_id  UUID;
BEGIN
  IF p_par IS NOT NULL THEN
    SELECT id, depth + 1 INTO v_pid, v_dep
      FROM bauth.idn_roles_template WHERE path = p_par;
    IF v_pid IS NULL THEN
      RAISE WARNING 'Padre no encontrado: path=% al insertar %', p_par, p_path;
      RETURN NULL;
    END IF;
  END IF;
  INSERT INTO bauth.idn_roles_template
    (tenant_id, parent_id, path, tipo, clave, name,
     valor, help, opciones, effect, verb_id, domain_number,
     depth, condition_expr)
  VALUES
    (p_ten, v_pid, p_path, p_tipo, p_clav,
     jsonb_build_object('es', p_name),
     p_val, p_help, p_opc, p_eff, p_verb, p_dnum,
     v_dep, p_cond)
  ON CONFLICT (path) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM bauth.idn_roles_template WHERE path = p_path;
  END IF;
  RETURN v_id;
END;
$func$;

